def greedy_construction(M, N, D):
    y = np.zeros(N)
    y[0] = 0
    for i in range(1, N):
        forbidden = []
        for j in range(i):
            dist = D / (i + 1 + j + 1)
            forbidden.append((y[j] - dist, y[j] + dist))
        forbidden.sort()
        current_y = 0
        for low, high in forbidden:
            if current_y < low:
                break
            current_y = max(current_y, high)
        if current_y > M:
            return None
        y[i] = current_y
    return y

